"use client"

import * as React from "react"
import useSWR from "swr"
import { Combobox, ComboboxItem } from "@/components/ui/combobox"

// Define Category type
export interface Category {
  id: number
  name: string
}

// Define fetcher function
const categoryFetcher = async (): Promise<Category[]> => {
  const response = await fetch('/api/categories')
  if (!response.ok) {
    throw new Error('Failed to fetch categories')
  }
  return response.json()
}

interface CategoryComboboxProps {
  value: number
  onChange: (value: number) => void
  placeholder?: string
  className?: string
  maxHeight?: string
}

export function CategoryCombobox({
  value,
  onChange,
  placeholder = "Select a category",
  className,
  maxHeight = "250px",
}: CategoryComboboxProps) {
  // Fetch categories with SWR
  const { data: categories = [], error, isLoading } = useSWR<Category[]>(
    'categories',
    categoryFetcher,
    {
      revalidateOnFocus: false,
      revalidateOnReconnect: false,
      refreshInterval: 60 * 60 * 1000, // Revalidate every hour
      dedupingInterval: 10000, // Dedupe requests within 10 seconds
      errorRetryCount: 3,
    }
  )

  // Format categories for combobox
  const categoryOptions: ComboboxItem[] = categories.map((category) => ({
    value: category.id.toString(),
    label: category.name,
  }))

  return (
    <Combobox
      items={categoryOptions}
      value={value ? value.toString() : ""}
      onChange={(value) => onChange(parseInt(value))}
      placeholder={isLoading ? "Loading categories..." : error ? "Error loading categories" : placeholder}
      emptyMessage={categories.length === 0 ? "No categories found" : "No results found"}
      searchPlaceholder="Search categories..."
      className={className}
      maxHeight={maxHeight}
    />
  )
} 