"use client"

import { useMemo } from "react"
import { ColumnDef } from "@tanstack/react-table"
import { DataTable } from "@/components/layout/data-table"
import { Transaction } from "@/app/types"
import { useTransactions } from "@/app/hooks/useTransactions"
import { Skeleton } from "@/components/ui/skeleton"

interface TransactionsDataTableProps {
  columns: ColumnDef<Transaction>[]
}

export function TransactionsDataTable({ columns }: TransactionsDataTableProps) {
  // Use our custom hook to fetch transactions
  const { transactions: data = [], isLoading, error } = useTransactions();

  const categories = useMemo(() => {
    const uniqueCategories = Array.from(new Set(data.map((item: Transaction) => item.category)))
      .filter((category): category is string => category !== undefined && category !== null)
    
    return uniqueCategories.map((category, i) => ({
      label: category,
      value: `${category}-${i}`,
    }))
  }, [data])

  if (error) {
    return <div className="p-4 text-center text-red-500">Failed to load transactions. Please try again.</div>;
  }

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-12 w-full" />
        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  return (
    <DataTable
      columns={columns}
      data={data}
      searchPlaceholder="Search transactions..."
    />
  )
} 